// Hand-written `ky` stub: the default export is callable, names its verbs as
// methods, and makes instances holding a `prefixUrl` and the hooks they run
// before every request.

export interface Hooks {
  beforeRequest?: Array<(request: Request) => Request | Response | void>;
}

export interface Options {
  method?: string;
  json?: unknown;
  prefixUrl?: string;
  timeout?: number;
  hooks?: Hooks;
}

export interface ResponsePromise extends Promise<Response> {
  json<T = unknown>(): Promise<T>;
}

export interface KyInstance {
  (url: string, options?: Options): ResponsePromise;
  get(url: string, options?: Options): ResponsePromise;
  post(url: string, options?: Options): ResponsePromise;
  create(defaults?: Options): KyInstance;
  extend(defaults?: Options): KyInstance;
}

declare const ky: KyInstance;
export default ky;
